def frequencies(grid):
    counts = [0] * 10
    for row in grid:
        for value in row:
            counts[value] += 1
    return counts

verification.test_code:
def frequencies(grid):
    counts = [0] * 10
    for row in grid:
        for value in row:
            counts[value] += 1
    return counts
assert frequencies([[2,2,0],[9,0,2]])==[2,0,3,0,0,0,0,0,0,1]
assert frequencies([[8]])[8]==1

